class player_controller : gameObject
{
    label ("motion")
    export float move_speed = 10;
    export float jump_height = 10;
    export float turn_speed = 10;    
    export bool is_grounded = false;

    label("references")
    export rigidbody rb;
    export transform shoot_point;
    export prefab bullet;

    float delta_time = 0;
    export Vector3 input_vector = Vector3(0,0,0);

    func start()
    {
        //connect signals
        Input.action("jump").just_released.connect(jump);
        Input.action("shoot").just_released.connect(shoot);
    }

    func update(float delta)
    {
        //update delta
        delta_time = delta;
        update_input();
    }

    func physicsUpdate(float delta)
    {
        Vector3 temp_velocity = rb.velocity;
        float rot = turn_speed * input_vector.x * delta;
        if(rot > turn_speed)
        {
           rot = turn_speed; 
        }
        if(rot < -turn_speed)
        {
           rot = -turn_speed; 
        }
        rb.angular_velocity.y = rot;

        Vector3 velocity_change = transform.forward * move_speed * delta * input_vector.y;
        temp_velocity += velocity_change;
        if(input_vector.y != 0)
        {
           print("velocity change: " & {velocity_change            }) ;
        }
        temp_velocity.y = rb.velocity.y;
        rb.velocity = temp_velocity;

    }

    func draw()
    {
    }

    //returns true if the player is on the ground
    func grounded() : bool
    {
         return (rb.velocity.y < 0.1); 
    }

    //process the players jump
